function handleOrder(req: Request) {
  const payload = JSON.parse(req.body);
  if (!isValid(payload)) throw new Error('bad');
  const order = mapToOrder(payload);
  db.save(order);
  emailService.sendReceipt(order);
  analytics.track('order', order.id);
  return { status: 'ok' };
}

class OrderService {
  constructor(private repo: OrderRepo, private notifier: EmailClient, private logger: Logger) {}
  async create(dto: OrderDto) {
    const errors = this.validate(dto);
    const entity = this.mapDto(dto);
    await this.repo.save(entity);
    await this.notifier.send(entity.customerEmail, 'receipt');
    this.logger.info('order.created', entity.id);
    return entity.id;
  }
}

